import { PASSWORD, expect, test } from "../../fixtures";

test.describe("sign in", () => {
  test(
    "unknown email is rejected the same way as a wrong password",
    { tag: "@AUTH-03" },
    async ({ request }) => {
      // Arrange: an address no seeded user has, made unique so parallel runs never collide.
      const email = `nobody-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@northwind.test`;

      // Act
      const response = await request.post("/api/auth/login", {
        data: { email, password: PASSWORD },
      });

      // Assert
      expect(response.status()).toBe(401);
      const body = await response.json();
      expect(body.error.code).toBe("invalid_credentials");
    },
  );
});
